    /**
     * Wrapper class to convert Response<Object> to Response<ResultSet>
     */
    private class ResponseWrapper<T> extends Response<T> {
        private final Response<Object> wrapped;
        private final String graphId;

        public ResponseWrapper(Response<Object> wrapped, String graphId) {
            super(null);
            this.wrapped = wrapped;
            this.graphId = graphId;
        }

        @Override
        public T get() {
            Object obj = wrapped.get();
            @SuppressWarnings("unchecked")
            ResultSet resultSet = new ResultSetImpl((List<Object>) obj, redisGraph, caches.getGraphCache(graphId));
            return (T) resultSet;
        }

        @Override
        public void set(Object obj) {
            wrapped.set(obj);
        }

        @Override
        public String toString() {
            return wrapped.toString();
        }
    }

    /**
     * Wrapper class to convert Response<Object> to Response<String>
     */
    private class StringResponseWrapper extends Response<String> {
        private final Response<Object> wrapped;

        public StringResponseWrapper(Response<Object> wrapped) {
            super(null);
            this.wrapped = wrapped;
        }

        @Override
        public String get() {
            Object obj = wrapped.get();
            return SafeEncoder.encode((byte[]) obj);
        }

        @Override
        public void set(Object obj) {
            wrapped.set(obj);
        }

        @Override
        public String toString() {
            return wrapped.toString();
        }
    }

